SELECT account_type, balance_bucket, closed_count FROM (SELECT account_type, CASE WHEN balance >= 69000 THEN 'high' WHEN balance >= 14000 THEN 'mid' ELSE 'low' END AS balance_bucket, SUM(CASE WHEN status = 'CLOSED' THEN 1 ELSE 0 END) AS closed_count FROM accounts GROUP BY account_type, CASE WHEN balance >= 69000 THEN 'high' WHEN balance >= 14000 THEN 'mid' ELSE 'low' END) AS agg WHERE closed_count < 51 ORDER BY balance_bucket, account_type LIMIT 10
